import java.io.*;
import java.util.*;

/** Persistent friend relationships; room invitations and presence are session state. */
final class SocialServer {
 final GunnyServer server;final CloudStore store;final Map<String,Boolean> memory=new HashMap<>();
 SocialServer(GunnyServer s){server=s;store=s.store;}
 List<Map<String,Object>> relations(String id)throws Exception{
  if(store instanceof CloudStore.Memory){List<Map<String,Object>> rows=new ArrayList<>();synchronized(memory){for(var e:memory.entrySet()){String[] pair=e.getKey().split(":");if(pair[0].equals(id)||pair[1].equals(id))rows.add(Map.of("sender",pair[0],"receiver",pair[1],"accepted",e.getValue()));}}return rows;}
  return ((List<?>)store.request("/rest/v1/gunny_friends?or=(sender.eq."+id+",receiver.eq."+id+")&select=sender,receiver,accepted","GET",null,true)).stream().map(Json::obj).toList();
 }
 CloudStore.Profile target(int id)throws Exception{
  if(store instanceof CloudStore.Memory m){for(var a:m.accounts.values())if(a.profile().publicId==id)return a.profile();throw new IllegalArgumentException("Không có ID này.");}
  List<?> rows=(List<?>)store.request("/rest/v1/profiles?public_id=eq."+id+"&select=id","GET",null,true);if(rows.isEmpty())throw new IllegalArgumentException("Không có ID này.");return store.profile(Json.str(Json.obj(rows.get(0)),"id"));
 }
 void friend(GunnyServer.Session s,int id,int mode)throws Exception{
  CloudStore.Profile p=target(id);if(p.id.equals(s.id))throw new IllegalArgumentException("Đây là ID của bạn.");
  if(store instanceof CloudStore.Memory){synchronized(memory){String forward=s.id+":"+p.id,reverse=p.id+":"+s.id;if(mode==0){if(!memory.containsKey(reverse))memory.putIfAbsent(forward,false);}else if(mode==1){if(!Boolean.FALSE.equals(memory.get(reverse)))throw new IllegalArgumentException("Không có yêu cầu này.");memory.put(reverse,true);}else if(mode==2){if(Boolean.FALSE.equals(memory.get(reverse)))memory.remove(reverse);}else throw new IllegalArgumentException("Sai thao tác.");}}
  else store.request("/rest/v1/rpc/gunny_friend_action","POST",Json.write(Map.of("p_user",s.id,"p_target",id,"p_mode",mode)),true);
 }
 boolean handles(String op){return Set.of("findfriend","presence","battleemote","battleemotes","social","friend","invite","inviteanswer","allyai","socialpulse","slot","emote").contains(op);}
 GunnyServer.Session online(String id){for(var s:server.sessions.values())if(s.id.equals(id)&&System.currentTimeMillis()-s.lastSeen<45000)return s;return null;}
 void person(DataOutputStream out,CloudStore.Profile p,boolean online)throws IOException{out.writeInt(p.publicId);out.writeUTF(p.name);out.writeBoolean(online);out.writeByte(p.gender);out.writeByte(p.skin);out.writeBoolean(p.custom);for(int v:p.look)out.writeByte(v);}
 void handle(String op,GunnyServer.Session s,DataInputStream in,DataOutputStream out)throws Exception{
  if(op.equals("presence")){out.writeInt((int)server.sessions.values().stream().filter(p->System.currentTimeMillis()-p.lastSeen<45000).map(p->p.id).distinct().count());return;}
  if(op.equals("battleemote")||op.equals("battleemotes")){var room=server.requireRoom(s);synchronized(room){if(room.phase!=1||room.slot(s)<0)throw new IllegalArgumentException("Chỉ dùng cảm xúc trong trận");long now=System.currentTimeMillis();if(op.equals("battleemote")){int value=in.readUnsignedByte(),seat=room.slot(s);if(value>5)throw new IllegalArgumentException("Sai cảm xúc");if(room.battleEmoteUntil[seat]-now>2200)throw new IllegalArgumentException("Chờ một chút trước khi gửi tiếp");room.battleEmotes[seat]=value;room.battleEmoteUntil[seat]=now+3000;}for(int i=0;i<6;i++){int remaining=(int)Math.max(0,room.battleEmoteUntil[i]-now);out.writeByte(remaining>0?room.battleEmotes[i]:255);out.writeShort(remaining);}}return;}
  if(op.equals("findfriend")){String q=in.readUTF().trim();if(q.length()<1||q.length()>40)throw new IllegalArgumentException("Nhập tên hoặc ID");List<CloudStore.Profile> found=new ArrayList<>();if(store instanceof CloudStore.Memory m){for(var a:m.accounts.values()){var p=a.profile();if(!p.id.equals(s.id)&&(String.valueOf(p.publicId).equals(q)||p.name.toLowerCase(java.util.Locale.ROOT).contains(q.toLowerCase(java.util.Locale.ROOT))))found.add(p);}}else{String predicate=q.matches("[0-9]{1,9}")?"public_id=eq."+q:"display_name=ilike."+java.net.URLEncoder.encode("*"+q.replace("*","").replace("%","")+"*",java.nio.charset.StandardCharsets.UTF_8);List<?> rows=(List<?>)store.request("/rest/v1/profiles?"+predicate+"&select=id&limit=32","GET",null,true);for(Object row:rows){var p=store.profile(Json.str(Json.obj(row),"id"));if(!p.id.equals(s.id))found.add(p);}}out.writeInt(s.profile.publicId);out.writeShort(Math.min(32,found.size()));for(int i=0;i<Math.min(32,found.size());i++)person(out,found.get(i),online(found.get(i).id)!=null);return;}
  if(op.equals("slot")){int seat=in.readUnsignedByte();var r=server.requireRoom(s);synchronized(r){if(r.host!=s||r.phase!=0||seat<0||seat==r.slot(s)||seat>=r.count)throw new IllegalArgumentException("Chỉ chủ phòng được đổi ô chờ.");if(r.members[seat]!=null)server.leave(r.members[seat]);else if(seat==2&&r.allyBot>=0)r.allyBot=-1;else if(r.selectedBots[seat]>=0)r.selectedBots[seat]=-1;else r.closedSlots^=1<<seat;r.refreshWaiting();server.lobby(out,r,s);}return;}
  if(op.equals("emote")){int value=in.readUnsignedByte();var r=server.requireRoom(s);synchronized(r){int seat=r.slot(s);if(seat<0||value>1)throw new IllegalArgumentException("Biểu cảm không hợp lệ.");r.emotes[seat]=value;server.lobby(out,r,s);}return;}
  if(op.equals("socialpulse")){out.writeInt(s.inviteRoom);out.writeUTF(s.inviteFrom);return;}
  if(op.equals("friend")){friend(s,in.readInt(),in.readUnsignedByte());out.writeUTF("Đã cập nhật bạn bè.");return;}
  if(op.equals("social")){int tab=in.readUnsignedByte();List<CloudStore.Profile> list=new ArrayList<>();if(tab==0||tab==3){for(var r:relations(s.id)){boolean accepted=Boolean.TRUE.equals(r.get("accepted"));String sender=(String)r.get("sender"),receiver=(String)r.get("receiver");if(tab==0&&accepted||tab==3&&!accepted&&receiver.equals(s.id))list.add(store.profile(sender.equals(s.id)?receiver:sender));}}
   else for(var p:server.sessions.values()){var room=server.rooms.get(p.room);if(p!=s&&online(p.id)!=null&&(tab!=1||room==null)&&list.stream().noneMatch(x->x.id.equals(p.id)))list.add(p.profile);}
   list.sort(Comparator.comparingInt(p->p.publicId));out.writeInt(s.profile.publicId);out.writeShort(Math.min(128,list.size()));for(int i=0;i<Math.min(128,list.size());i++)person(out,list.get(i),online(list.get(i).id)!=null);return;}
  if(op.equals("invite")){int id=in.readInt();var room=server.requireRoom(s);CloudStore.Profile p=target(id);var peer=online(p.id);synchronized(room){if(room.phase!=0||room.kind==1&&room.timedOut||!room.customAllies&&room.kind!=1&&room.kind!=2)throw new IllegalArgumentException("Chỉ mời vào phòng riêng đang chờ.");boolean empty=false;int team=room.kind==1?1:room.slot(s)%2;for(int i=team;i<room.count;i+=2)if(room.members[i]==null&&(room.closedSlots&(1<<i))==0&&room.selectedBots[i]<0&&!(i==2&&room.allyBot>=0))empty=true;if(!empty)throw new IllegalArgumentException("Đội đã đủ người.");if(peer==null||peer==s)throw new IllegalArgumentException("Người chơi không online.");var other=server.rooms.get(peer.room);if(other!=null&&other.phase!=0)throw new IllegalArgumentException("Người chơi đang trong trận.");peer.inviteRoom=room.id;peer.inviteTeam=team;peer.inviteFrom=s.profile.name;}out.writeUTF("Đã gửi lời mời vào đội.");return;}
  if(op.equals("inviteanswer")){boolean accept=in.readBoolean();var room=server.rooms.get(s.inviteRoom);int team=s.inviteTeam;s.inviteRoom=0;if(!accept){out.writeBoolean(false);return;}if(room==null)throw new IllegalArgumentException("Lời mời đã hết hạn.");if(room.host.items!=s.items||room.host.itemVersion!=s.itemVersion||room.host.arsenal!=s.arsenal||room.host.equipment!=s.equipment)throw new IllegalArgumentException("Hai máy cần cùng bản 7.4.0.");if(s.room==room.id)throw new IllegalArgumentException("Bạn đã ở trong phòng.");var current=server.rooms.get(s.room);if(current!=null&&current.phase!=0)throw new IllegalArgumentException("Bạn đang trong trận.");synchronized(room){if(room.phase!=0||room.kind==1&&room.timedOut)throw new IllegalArgumentException("Phòng không còn chờ trận.");boolean available=false;for(int i=team;i<room.count;i+=2)if(room.members[i]==null&&(room.closedSlots&(1<<i))==0&&room.selectedBots[i]<0&&!(i==2&&room.allyBot>=0))available=true;if(!available)throw new IllegalArgumentException("Đội đã đủ người.");}server.leave(s);synchronized(room){if(room.phase!=0||room.kind==1&&room.timedOut)throw new IllegalArgumentException("Phòng không còn chờ trận.");int slot=-1;for(int i=team;i<room.count;i+=2)if(room.members[i]==null&&(room.closedSlots&(1<<i))==0&&room.selectedBots[i]<0&&!(i==2&&room.allyBot>=0))slot=i;if(slot<0)throw new IllegalArgumentException("Đội đã đủ người.");room.members[slot]=s;s.room=room.id;s.armed=room.kind==1;room.refreshWaiting();out.writeBoolean(true);server.lobby(out,room,s);}return;}
  if(op.equals("allyai")){int bot=in.readByte();var room=server.requireRoom(s);synchronized(room){if(room.phase!=0||room.slot(s)<0||bot< -1||bot>7)throw new IllegalArgumentException("Không thể mời AI lúc này.");if(room.kind==2){int seat=-1;for(int i=room.slot(s)%2;i<room.count;i+=2)if(room.members[i]==null&&room.selectedBots[i]<0&&(room.closedSlots&(1<<i))==0){seat=i;break;}if(seat<0)throw new IllegalArgumentException("Đội đã đầy.");room.selectedBots[seat]=bot;}else{if(s!=room.host||!room.customAllies||room.members[2]!=null||(room.closedSlots&4)!=0)throw new IllegalArgumentException("Ô đồng minh không còn trống.");room.allyBot=bot;}room.refreshWaiting();server.lobby(out,room,s);}return;}

 }
}
